"""Audit services/ against SPEC.md (rev 7 clauses C1-C15)."""
import ast
import json
import os
import re
import sys

ROOT = "/private/var/folders/w_/swqg2n117dzdrptxy6074cqw0000gp/T/w/c6197ad26cb5"
SERVICES = os.path.join(ROOT, "services")

LFS_MARK = "version https://git-lfs.github.com/spec/v1"


def read(path):
    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        return fh.read()


def py_files(svc):
    out = []
    for base, _dirs, files in os.walk(os.path.join(svc, "src")):
        for f in files:
            if f.endswith(".py"):
                out.append(os.path.join(base, f))
    return sorted(out)


def is_lfs(path):
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as fh:
            first = fh.readline().rstrip("\r\n")
    except OSError:
        return False
    return first == LFS_MARK or first.startswith(LFS_MARK)


def service_files(svc):
    out = []
    for base, _dirs, files in os.walk(svc):
        for f in files:
            out.append(os.path.join(base, f))
    return sorted(out)


def parse_py(path):
    try:
        return ast.parse(read(path), filename=path)
    except SyntaxError as exc:
        return exc


def check(svc_name):
    svc = os.path.join(SERVICES, svc_name)
    ev = {}
    cfg_path = os.path.join(svc, "config.json")
    cfg = {}
    cfg_err = None
    if os.path.isfile(cfg_path):
        try:
            cfg = json.loads(read(cfg_path))
        except Exception as exc:  # noqa: BLE001
            cfg_err = str(exc)
    ev["config_error"] = cfg_err

    public = cfg.get("exposure") == "public"
    ev["public"] = public

