    t = cfg.get("timeout_s")
    ev["C1"] = (not public) or (type(t) is int and t <= 30) or (type(t) is float and t <= 30)

    # C2
    hp = os.path.join(svc, "src", "handlers.py")
    tree = parse_py(hp) if os.path.isfile(hp) else None
    bad_doc = []
    if isinstance(tree, ast.AST):
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name.startswith("handle_"):
                if ast.get_docstring(node) is None:
                    bad_doc.append(node.name)
    ev["C2"] = not bad_doc
    ev["C2_detail"] = bad_doc

    # C3
    prints = []
    for p in py_files(svc):
        tr = parse_py(p)
        if not isinstance(tr, ast.AST):
