    ev["C3"] = not prints
    ev["C3_detail"] = prints

    # C4
    r = cfg.get("retries")
    ev["C4"] = type(r) is int and 1 <= r <= 5
    ev["C4_detail"] = r

    # C5
    df = os.path.join(svc, "Dockerfile")
    from_bad = []
    from_lines = []
    if os.path.isfile(df):
        for i, line in enumerate(read(df).splitlines(), 1):
            s = line.strip()
            if re.match(r"(?i)^FROM\s", s):
                from_lines.append((i, s))
                toks = s.split()[1:]
                toks = [x for x in toks if not x.startswith("--")]
                image = toks[0] if toks else ""
                ok = bool(re.fullmatch(r"[^@\s]+@sha256:[0-9a-f]{64}", image))
                if not ok:
                    from_bad.append((i, image))
    else:
        from_bad.append((0, "<no Dockerfile>"))
    ev["C5"] = not from_bad
    ev["C5_detail"] = from_bad
    ev["C5_from"] = from_lines

    # C6
    users = []
    if os.path.isfile(df):
        for i, line in enumerate(read(df).splitlines(), 1):
            s = line.strip()
            if re.match(r"(?i)^USER\s+", s):
                users.append((i, s.split(None, 1)[1].strip()))
    if not users:
        ev["C6"] = False
        ev["C6_detail"] = "no USER line"
    else:
        last = users[-1][1]
        parts = re.split(r"[:]", last)
        ev["C6"] = not any(x.lower() == "root" or x == "0" for x in parts)
        ev["C6_detail"] = users

    # C7
    rd = os.path.join(svc, "README.md")
    lines = read(rd).splitlines() if os.path.isfile(rd) else []
    ev["C7"] = "## Runbook" in lines
    ev["C7_detail"] = [l for l in lines if l.lstrip().startswith("##")]

    # C8
    co = os.path.join(svc, "CODEOWNERS")
    team = cfg.get("team")
    want = "@team-%s" % team if isinstance(team, str) else None
    rules = []
    star_owners = []
    if os.path.isfile(co):
        for line in read(co).splitlines():
            s = line.strip()
            if not s or s.startswith("#"):
                continue
            toks = s.split()
            if toks[0] == "*":
                star_owners.extend(toks[1:])
            rules.append(toks)
    ev["C8"] = bool(want) and want in star_owners
    ev["C8_detail"] = {"want": want, "star": star_owners}

    # C9
    secrets = []
    for p in py_files(svc):
        tr = parse_py(p)
        if not isinstance(tr, ast.AST):
            continue
        for node in ast.walk(tr):
            vals = []
            if isinstance(node, ast.Constant) and isinstance(node.value, str):
                vals = [node.value]
            elif isinstance(node, ast.JoinedStr):
