            for val in vals:
                if val.startswith("sk_live_") or val.startswith("AKIA"):
                    secrets.append("%s:%d:%s" % (os.path.relpath(p, svc), getattr(node, "lineno", 0), val[:24]))
    ev["C9"] = not secrets
    ev["C9_detail"] = secrets

    # C10
    hc = cfg.get("healthcheck")
    hc_ok = isinstance(hc, str) and hc.startswith("/") and len(hc) > 1
    seg = hc.rstrip("/").rsplit("/", 1)[-1] if isinstance(hc, str) else None
    want_fn = "handle_%s" % seg if seg else None
    defs = set()
    if isinstance(tree, ast.AST):
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                defs.add(node.name)
    ev["C10"] = bool(hc_ok and want_fn in defs)
    ev["C10_detail"] = {"healthcheck": hc, "want": want_fn, "defs": sorted(defs)}

    # C11
    p_, m_ = cfg.get("port"), cfg.get("metrics_port")
    ev["C11"] = p_ is not None and m_ is not None and p_ != m_
    ev["C11_detail"] = (p_, m_)

    # C12
    req = os.path.join(svc, "requirements.txt")
    req_bad = []
    if os.path.isfile(req):
        for i, line in enumerate(read(req).splitlines(), 1):
            s = line.strip()
            if not s or s.startswith("#"):
                continue
            body = s.split(" #", 1)[0].strip()
            m = re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]*(\[[^\]]+\])?==([0-9][A-Za-z0-9.+!-]*)", body)
            if not m:
                req_bad.append((i, s))
    else:
        req_bad.append((0, "<no requirements.txt>"))
    ev["C12"] = not req_bad
    ev["C12_detail"] = req_bad

    # C13
    ev["C13"] = cfg.get("log_level") != "DEBUG"
    ev["C13_detail"] = cfg.get("log_level")

    # C14
    mb = cfg.get("max_body_kb")
    ev["C14"] = (not public) or (type(mb) is int and mb <= 1024)
    ev["C14_detail"] = mb

    # C15
    tests = os.path.join(svc, "tests")
    names = os.listdir(tests) if os.path.isdir(tests) else []
    ev["C15"] = any(n.startswith("test_") and n.endswith(".py") for n in names)
    ev["C15_detail"] = sorted(names)

    return ev


def main():
    names = sorted(d for d in os.listdir(SERVICES) if os.path.isdir(os.path.join(SERVICES, d)))
    verbose = "-v" in sys.argv
    reports = {}
    for name in names:
        svc = os.path.join(SERVICES, name)
        ptrs = [os.path.relpath(p, svc) for p in service_files(svc) if is_lfs(p)]
        ev = check(name)
        if ptrs:
            reports[name] = {"service": name, "status": "unverifiable", "violations": [], "_ptrs": ptrs}
            continue
        viol = []
        for i in range(1, 16):
