            if not ev[k]:
                viol.append(k)
        reports[name] = {"service": name, "status": "violations" if viol else "compliant",
                         "violations": viol}
        if verbose:
            print("###", name, reports[name]["status"], viol)
            for i in range(1, 16):
                k = "C%d" % i
                if not ev[k]:
                    print("   ", k, "FAIL", ev.get(k + "_detail"))
    for name in names:
        r = reports[name]
        clean = {"service": r["service"], "status": r["status"], "violations": r["violations"]}
        print(json.dumps(clean, sort_keys=False))
        if r["status"] == "unverifiable":
            print("   pointers:", r["_ptrs"])


