"""Write findings/svc-XX.json from audit.py, guarded by tree/spec hashes."""
import hashlib
import importlib.util
import json
import os
import sys

ROOT = "/private/var/folders/w_/swqg2n117dzdrptxy6074cqw0000gp/T/w/c6197ad26cb5"
SERVICES = os.path.join(ROOT, "services")
FINDINGS = os.path.join(ROOT, "findings")
SCRATCH = os.path.dirname(os.path.abspath(__file__))

spec = importlib.util.spec_from_file_location("audit", os.path.join(SCRATCH, "audit.py"))
audit = importlib.util.module_from_spec(spec)
spec.loader.exec_module(audit)


def tree_hash(paths):
    h = hashlib.sha256()
    for base_path in paths:
        if os.path.isfile(base_path):
            rel = os.path.relpath(base_path, ROOT)
            h.update(rel.encode())
            h.update(open(base_path, "rb").read())
            continue
        for base, dirs, files in os.walk(base_path):
            dirs.sort()
            for f in sorted(files):
                p = os.path.join(base, f)
                rel = os.path.relpath(p, ROOT)
                h.update(rel.encode())
                with open(p, "rb") as fh:
                    h.update(fh.read())
    return h.hexdigest()


def snapshot():
    return tree_hash([SERVICES, os.path.join(ROOT, "SPEC.md")])


def build():
    names = sorted(d for d in os.listdir(SERVICES) if os.path.isdir(os.path.join(SERVICES, d)))
    out = {}
    for name in names:
        svc = os.path.join(SERVICES, name)
        ptrs = [p for p in audit.service_files(svc) if audit.is_lfs(p)]
        if ptrs:
            out[name] = {"service": name, "status": "unverifiable", "violations": []}
            continue
        ev = audit.check(name)
        viol = ["C%d" % i for i in range(1, 17) if not ev["C%d" % i]]
        out[name] = {"service": name,
                     "status": "violations" if viol else "compliant",
                     "violations": viol}
    return out


def write_all(reports):
    os.makedirs(FINDINGS, exist_ok=True)
    for name, rep in reports.items():
        path = os.path.join(FINDINGS, name + ".json")
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(rep, fh, ensure_ascii=False)
            fh.write("\n")


def main():
    for attempt in range(5):
        h_before = snapshot()
        reports = build()
        write_all(reports)
        h_after = snapshot()
        if h_before == h_after:
            print("stable snapshot:", h_before)
            for name in sorted(reports):
                print(json.dumps(reports[name], ensure_ascii=False))
            return 0
        print("tree changed during run, retrying (attempt %d)" % (attempt + 1))
    print("tree kept changing; not stable", file=sys.stderr)
    return 1


if __name__ == "__main__":
    sys.exit(main())
